import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';

const AdvertisementManager = () => {
  const [ads, setAds] = useState([]);
  const [loading, setLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [error, setError] = useState(null);
  const [toast, setToast] = useState({ show: false, message: '', type: 'success' });
  const navigate = useNavigate();

  const [formData, setFormData] = useState({
    id: null,
    title: '',
    mediaType: 'image',
    mediaUrl: '',
    bannerType: 'hero',
    pages: [],
    tag: '',
    tagline: '',
    deal: '',
    discount: '',
    dealSuffix: 'OFF',
    subtitle: '',
    ctaText: '',
    ctaLink: '',
    isActive: true,
    order: 0
  });

  const API_URL = 'http://localhost:5001/api/advertisements';
  const UPLOAD_URL = 'http://localhost:5001/api/upload/ad';

  const fetchAds = async () => {
    try {
      setLoading(true);
      const token = localStorage.getItem('adminToken');
      const { data } = await axios.get(`${API_URL}/admin`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setAds(data);
    } catch (err) {
      setError("Failed to fetch advertisements.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchAds();
  }, []);

  const showToast = (message, type = 'success') => {
    setToast({ show: true, message, type });
    setTimeout(() => setToast({ show: false, message: '', type: 'success' }), 3000);
  };

  const getAuthHeaders = () => {
    const token = localStorage.getItem('adminToken');
    return { headers: { Authorization: `Bearer ${token}` } };
  };

  const resetForm = () => {
    setFormData({
      id: null,
      title: '',
      mediaType: 'image',
      mediaUrl: '',
      bannerType: 'hero',
      pages: [],
      tag: '',
      tagline: '',
      deal: '',
      discount: '',
      dealSuffix: 'OFF',
      subtitle: '',
      ctaText: '',
      ctaLink: '',
      isActive: true,
      order: 0
    });
    setIsEditing(false);
    setIsModalOpen(false);
  };

  const handleInputChange = (e) => {
    const { name, value, type, checked } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : value
    }));
  };

  const handlePageToggle = (pageKey) => {
    setFormData(prev => ({
      ...prev,
      pages: prev.pages.includes(pageKey)
        ? prev.pages.filter(p => p !== pageKey)
        : [...prev.pages, pageKey]
    }));
  };

  const handleMediaUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;

    const uploadData = new FormData();
    uploadData.append('media', file);

    try {
      setIsUploading(true);
      const { data } = await axios.post(UPLOAD_URL, uploadData, getAuthHeaders());
      setFormData(prev => ({
        ...prev,
        mediaUrl: data.url,
        mediaType: data.mediaType
      }));
      showToast('Media uploaded successfully');
    } catch (err) {
      showToast('Failed to upload media', 'error');
    } finally {
      setIsUploading(false);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      if (isEditing) {
        await axios.put(`${API_URL}/${formData.id}`, formData, getAuthHeaders());
        showToast('Advertisement updated');
      } else {
        await axios.post(API_URL, formData, getAuthHeaders());
        showToast('Advertisement created');
      }
      resetForm();
      fetchAds();
    } catch (err) {
      showToast('Failed to save advertisement', 'error');
    }
  };

  const handleToggleActive = async (id) => {
    try {
      await axios.patch(`${API_URL}/${id}/toggle`, {}, getAuthHeaders());
      fetchAds();
      showToast('Status updated');
    } catch (err) {
      showToast('Failed to toggle status', 'error');
    }
  };

  const handleDelete = async (id) => {
    if (!window.confirm('Delete this advertisement?')) return;
    try {
      await axios.delete(`${API_URL}/${id}`, getAuthHeaders());
      fetchAds();
      showToast('Advertisement deleted');
    } catch (err) {
      showToast('Failed to delete', 'error');
    }
  };

  const handleEditClick = (ad) => {
    setFormData({
      id: ad._id,
      title: ad.title,
      mediaType: ad.mediaType,
      mediaUrl: ad.mediaUrl,
      bannerType: ad.bannerType,
      pages: ad.pages || [],
      tag: ad.tag || '',
      tagline: ad.tagline || '',
      deal: ad.deal || '',
      discount: ad.discount || '',
      dealSuffix: ad.dealSuffix || 'OFF',
      subtitle: ad.subtitle || '',
      ctaText: ad.ctaText || '',
      ctaLink: ad.ctaLink || '',
      isActive: ad.isActive,
      order: ad.order || 0
    });
    setIsEditing(true);
    setIsModalOpen(true);
  };

  const targetPages = [
    { key: 'home', label: 'Home Page' },
    { key: 'men', label: 'Men\'s Page' },
    { key: 'women', label: 'Women\'s Page' },
    { key: 'apparel', label: 'Apparel' },
    { key: 'classics', label: 'Classics' },
    { key: 'sports', label: 'Sports' },
    { key: 'shop', label: 'Shop Page' },
  ];

  return (
    <div className="min-h-screen bg-gray-50 flex">
      {/* Sidebar Placeholder */}
      <div className="w-64 bg-gray-900 text-white flex-shrink-0">
        <div className="p-6">
          <h1 className="text-xl font-bold tracking-tight">Admin Portal</h1>
        </div>
        <nav className="mt-6 px-4 space-y-1">
          <button onClick={() => navigate('/admin')} className="w-full flex items-center gap-3 px-4 py-3 text-sm font-medium text-gray-300 hover:text-white hover:bg-gray-800 rounded-lg transition-all">
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4" /></svg>
            Products
          </button>
          <button className="w-full flex items-center gap-3 px-4 py-3 text-sm font-medium text-white bg-gray-800 rounded-lg transition-all">
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M11 5.882V19.24a1.76 1.76 0 01-3.417.592l-2.147-6.15M18 13a3 3 0 100-6M5.436 13.683A4.001 4.001 0 017 6h1.832c4.1 0 7.625-1.234 9.168-3v14c-1.543-1.766-5.067-3-9.168-3H7a3.988 3.988 0 01-1.564-.317z" /></svg>
            Advertisements
          </button>
          <button onClick={() => navigate('/admin-orders')} className="w-full flex items-center gap-3 px-4 py-3 text-sm font-medium text-gray-300 hover:text-white hover:bg-gray-800 rounded-lg transition-all">
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-3 7h3m-3 4h3m-6-4h.01M9 16h.01" /></svg>
            Orders
          </button>
        </nav>
      </div>

      {/* Main Content */}
      <div className="flex-1 flex flex-col min-w-0 overflow-hidden">
        {/* Header */}
        <header className="bg-white border-b border-gray-200 h-16 flex items-center justify-between px-8 shrink-0">
          <div className="flex items-center gap-4">
            <h2 className="text-lg font-bold text-gray-900 tracking-tight">Advertisement Management</h2>
            <span className="bg-gray-100 text-gray-600 text-[10px] font-bold px-2 py-1 rounded-full uppercase tracking-wider">
              {ads.length} Total
            </span>
          </div>
          <button 
            onClick={() => { resetForm(); setIsModalOpen(true); }}
            className="inline-flex items-center gap-2 bg-gray-900 text-white px-5 py-2.5 rounded-lg text-sm font-bold hover:bg-black transition-all shadow-sm active:scale-95"
          >
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v16m8-8H4" /></svg>
            Create New Ad
          </button>
        </header>

        {/* Content Area */}
        <main className="flex-1 overflow-y-auto p-8">
          <div className="max-w-[1200px] mx-auto">
            {loading ? (
              <div className="flex justify-center items-center h-64">
                <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-gray-900"></div>
              </div>
            ) : ads.length === 0 ? (
              <div className="bg-white rounded-2xl border border-gray-100 p-12 text-center shadow-sm">
                <div className="bg-gray-50 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4">
                  <svg className="w-8 h-8 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M11 5.882V19.24a1.76 1.76 0 01-3.417.592l-2.147-6.15M18 13a3 3 0 100-6M5.436 13.683A4.001 4.001 0 017 6h1.832c4.1 0 7.625-1.234 9.168-3v14c-1.543-1.766-5.067-3-9.168-3H7a3.988 3.988 0 01-1.564-.317z" /></svg>
                </div>
                <h3 className="text-lg font-bold text-gray-900 mb-1">No Advertisements Found</h3>
                <p className="text-gray-500 text-sm mb-6 max-w-sm mx-auto">Start by creating your first hero carousel or ad strip banner to display on your website.</p>
                <button onClick={() => setIsModalOpen(true)} className="text-gray-900 font-bold text-sm underline hover:text-black">Add your first ad</button>
              </div>
            ) : (
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {ads.map((ad) => (
                  <div key={ad._id} className="bg-white rounded-2xl border border-gray-100 overflow-hidden shadow-sm hover:shadow-md transition-all group flex flex-col">
                    <div className="relative h-44 bg-gray-100 overflow-hidden shrink-0">
                      {ad.mediaType === 'video' ? (
                        <video src={ad.mediaUrl} className="w-full h-full object-cover" muted loop autoPlay />
                      ) : (
                        <img src={ad.mediaUrl} alt={ad.title} className="w-full h-full object-cover" />
                      )}
                      <div className="absolute top-3 left-3 flex gap-2">
                        <span className={`px-2 py-1 rounded-md text-[10px] font-bold uppercase tracking-wider ${ad.bannerType === 'hero' ? 'bg-blue-600 text-white' : ad.bannerType === 'strip' ? 'bg-green-600 text-white' : 'bg-purple-600 text-white'}`}>
                          {ad.bannerType}
                        </span>
                      </div>
                      <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center gap-2">
                         <button onClick={() => handleEditClick(ad)} className="bg-white text-gray-900 p-2 rounded-lg hover:bg-gray-100"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" /></svg></button>
                         <button onClick={() => handleDelete(ad._id)} className="bg-white text-red-600 p-2 rounded-lg hover:bg-red-50"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg></button>
                      </div>
                    </div>
                    <div className="p-5 flex-1 flex flex-col">
                      <div className="flex justify-between items-start mb-2">
                        <h4 className="font-bold text-gray-900 text-base leading-tight">{ad.title}</h4>
                        <button 
                          onClick={() => handleToggleActive(ad._id)}
                          className={`w-10 h-5 rounded-full relative transition-colors ${ad.isActive ? 'bg-green-500' : 'bg-gray-300'}`}
                        >
                          <div className={`absolute top-0.5 w-4 h-4 bg-white rounded-full transition-transform ${ad.isActive ? 'translate-x-[22px]' : 'translate-x-[2px]'}`} />
                        </button>
                      </div>
                      <div className="flex flex-wrap gap-1 mb-4">
                        {ad.pages.map(p => (
                          <span key={p} className="bg-gray-50 text-gray-500 text-[10px] font-bold px-2 py-0.5 rounded border border-gray-100 uppercase tracking-tighter">{p}</span>
                        ))}
                      </div>
                      {ad.bannerType === 'strip' && (
                        <div className="bg-[#fdfbf7] border border-[#f3e3cc] p-3 rounded-xl mb-4 text-[11px]">
                          <p className="font-bold text-[#b45309] uppercase tracking-wider">{ad.tag}</p>
                          <p className="text-[#92400e] opacity-80">{ad.tagline}</p>
                          <p className="mt-1 font-black text-gray-900">{ad.deal} {ad.discount} {ad.dealSuffix}</p>
                        </div>
                      )}
                      {ad.bannerType === 'middle' && (
                        <div className="bg-purple-50 border border-purple-100 p-3 rounded-xl mb-4 text-[11px]">
                          <p className="font-bold text-purple-700 uppercase tracking-wider">{ad.tag}</p>
                          <p className="text-gray-900 font-extrabold text-xs">{ad.title}</p>
                          <p className="text-gray-500">{ad.subtitle}</p>
                        </div>
                      )}
                      <div className="mt-auto pt-4 border-t border-gray-50 flex items-center justify-between text-[11px] text-gray-400">
                        <span>Order: {ad.order}</span>
                        <span className="font-medium underline text-gray-600 truncate max-w-[150px]">{ad.ctaLink}</span>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        </main>
      </div>

      {/* Modal / Slide-over */}
      {isModalOpen && (
        <div className="fixed inset-0 z-50 overflow-hidden">
          <div className="absolute inset-0 bg-black/60 backdrop-blur-sm transition-opacity" onClick={resetForm} />
          <div className="absolute inset-y-0 right-0 max-w-2xl w-full bg-white shadow-2xl flex flex-col transform transition-transform duration-300 ease-in-out">
            <header className="px-8 py-6 border-b border-gray-100 flex items-center justify-between">
              <div>
                <h3 className="text-xl font-bold text-gray-900">{isEditing ? 'Edit Advertisement' : 'New Advertisement'}</h3>
                <p className="text-sm text-gray-500 mt-1">Configure your media and targeting</p>
              </div>
              <button onClick={resetForm} className="text-gray-400 hover:text-gray-900 p-2"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg></button>
            </header>

            <form id="ad-form" onSubmit={handleSubmit} className="flex-1 overflow-y-auto px-8 py-6 space-y-8">
              {/* Type & Page Targeting */}
              <div className="grid grid-cols-2 gap-8 pt-2">
                <div>
                   <label className="block text-[11px] font-bold text-gray-400 uppercase tracking-widest mb-3">Banner Type</label>
                   <div className="flex gap-2">
                     {['hero', 'strip', 'middle'].map(type => (
                       <button
                         key={type}
                         type="button"
                         onClick={() => setFormData(prev => ({ ...prev, bannerType: type }))}
                         className={`flex-1 py-3 px-4 rounded-xl border text-sm font-bold capitalize transition-all ${formData.bannerType === type ? 'bg-gray-900 border-gray-900 text-white shadow-lg' : 'bg-white border-gray-200 text-gray-500 hover:border-gray-400'}`}
                       >
                         {type}
                       </button>
                     ))}
                   </div>
                </div>
                <div>
                  <label className="block text-[11px] font-bold text-gray-400 uppercase tracking-widest mb-3">Order</label>
                  <input type="number" name="order" value={formData.order} onChange={handleInputChange} className="w-full bg-gray-50 border-none rounded-xl px-4 py-3 text-sm focus:ring-2 focus:ring-gray-900" />
                </div>
              </div>

              <div>
                <label className="block text-[11px] font-bold text-gray-400 uppercase tracking-widest mb-3">Target Pages</label>
                <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
                  {targetPages.map(({ key, label }) => (
                    <label key={key} className={`flex items-center gap-3 p-3 rounded-xl border cursor-pointer transition-all ${formData.pages.includes(key) ? 'bg-gray-50 border-gray-900 ring-1 ring-gray-900' : 'bg-white border-gray-100 hover:border-gray-300'}`}>
                      <input type="checkbox" checked={formData.pages.includes(key)} onChange={() => handlePageToggle(key)} className="sr-only" />
                      <div className={`w-4 h-4 rounded-full border-2 flex items-center justify-center transition-all ${formData.pages.includes(key) ? 'bg-gray-900 border-gray-900' : 'border-gray-300'}`}>
                        {formData.pages.includes(key) && <div className="w-1.5 h-1.5 bg-white rounded-full" />}
                      </div>
                      <span className={`text-xs font-bold leading-none ${formData.pages.includes(key) ? 'text-gray-900' : 'text-gray-500'}`}>{label}</span>
                    </label>
                  ))}
                </div>
              </div>

              {/* Title & Media */}
              <div className="space-y-6">
                <div>
                  <label className="block text-[11px] font-bold text-gray-400 uppercase tracking-widest mb-3">Admin Title</label>
                  <input type="text" name="title" value={formData.title} onChange={handleInputChange} className="w-full bg-gray-50 border-none rounded-xl px-4 py-4 text-sm font-medium focus:ring-2 focus:ring-gray-900" placeholder="e.g. Summer Hero Video" required />
                </div>

                <div>
                  <label className="block text-[11px] font-bold text-gray-400 uppercase tracking-widest mb-3">Media (Cloudinary)</label>
                  <div className={`relative h-56 rounded-2xl overflow-hidden border-2 border-dashed transition-all flex flex-col items-center justify-center ${formData.mediaUrl ? 'border-solid border-gray-900' : 'border-gray-200 bg-gray-50'}`}>
                    {formData.mediaUrl ? (
                      <>
                        {formData.mediaType === 'video' ? (
                          <video src={formData.mediaUrl} className="w-full h-full object-cover" muted loop autoPlay />
                        ) : (
                          <img src={formData.mediaUrl} alt="Preview" className="w-full h-full object-cover" />
                        )}
                        <button type="button" onClick={() => setFormData(prev => ({ ...prev, mediaUrl: '', mediaType: 'image' }))} className="absolute top-4 right-4 bg-white/90 backdrop-blur p-2 rounded-xl text-red-600 shadow-xl hover:bg-white"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg></button>
                      </>
                    ) : (
                      <div className="text-center p-8">
                        <div className="bg-white w-12 h-12 rounded-2xl shadow-sm flex items-center justify-center mx-auto mb-4">
                           <svg className="w-6 h-6 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" /></svg>
                        </div>
                        <p className="text-xs font-bold text-gray-900 mb-1">{isUploading ? 'Uploading...' : 'Upload Image or Video'}</p>
                        <p className="text-[10px] text-gray-400 px-8">High-res JPG/PNG or MP4 video for hero banners</p>
                        <input type="file" accept="image/*,video/*" onChange={handleMediaUpload} disabled={isUploading} className="absolute inset-0 opacity-0 cursor-pointer" />
                      </div>
                    )}
                  </div>
                </div>
              </div>

              {/* Middle Banner Specific Fields */}
              {formData.bannerType === 'middle' && (
                <div className="bg-purple-50 rounded-2xl p-6 space-y-6 animate-fadeIn">
                   <h5 className="text-[11px] font-black text-purple-400 uppercase tracking-widest flex items-center gap-2">
                     <div className="w-1.5 h-1.5 bg-purple-400 rounded-full" />
                     Middle Banner Details
                   </h5>
                   <div className="grid grid-cols-2 gap-4">
                     <div>
                       <label className="block text-[10px] font-bold text-gray-500 uppercase mb-1.5">Top Tagline (e.g. #NewStyles)</label>
                       <input type="text" name="tag" value={formData.tag} onChange={handleInputChange} className="w-full bg-white border-none rounded-xl px-4 py-3 text-xs font-bold focus:ring-2 focus:ring-purple-900" />
                     </div>
                     <div>
                       <label className="block text-[10px] font-bold text-gray-500 uppercase mb-1.5">Sub-title (e.g. STYLES FOR EVERY...)</label>
                       <input type="text" name="subtitle" value={formData.subtitle} onChange={handleInputChange} className="w-full bg-white border-none rounded-xl px-4 py-3 text-xs focus:ring-2 focus:ring-purple-900" />
                     </div>
                   </div>
                </div>
              )}

              {/* Strip Specific Fields */}
              {formData.bannerType === 'strip' && (
                <div className="bg-gray-50 rounded-2xl p-6 space-y-6 animate-fadeIn">
                   <h5 className="text-[11px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">
                     <div className="w-1.5 h-1.5 bg-gray-400 rounded-full" />
                     Strip Details
                   </h5>
                   <div className="grid grid-cols-2 gap-4">
                     <div>
                       <label className="block text-[10px] font-bold text-gray-500 uppercase mb-1.5">Tag (e.g. BESTSELLERS)</label>
                       <input type="text" name="tag" value={formData.tag} onChange={handleInputChange} className="w-full bg-white border-none rounded-xl px-4 py-3 text-xs font-bold focus:ring-2 focus:ring-gray-900" />
                     </div>
                     <div>
                       <label className="block text-[10px] font-bold text-gray-500 uppercase mb-1.5">Tagline</label>
                       <input type="text" name="tagline" value={formData.tagline} onChange={handleInputChange} className="w-full bg-white border-none rounded-xl px-4 py-3 text-xs focus:ring-2 focus:ring-gray-900" />
                     </div>
                   </div>
                   <div className="grid grid-cols-3 gap-4">
                     <div>
                       <label className="block text-[10px] font-bold text-gray-500 uppercase mb-1.5">Deal Prefix</label>
                       <input type="text" name="deal" value={formData.deal} onChange={handleInputChange} className="w-full bg-white border-none rounded-xl px-4 py-3 text-xs focus:ring-2 focus:ring-gray-900" placeholder="UPTO" />
                     </div>
                     <div>
                       <label className="block text-[10px] font-bold text-gray-500 uppercase mb-1.5">Discount</label>
                       <input type="text" name="discount" value={formData.discount} onChange={handleInputChange} className="w-full bg-white border-none rounded-xl px-4 py-3 text-xs font-black focus:ring-2 focus:ring-gray-900" placeholder="30%" />
                     </div>
                     <div>
                       <label className="block text-[10px] font-bold text-gray-500 uppercase mb-1.5">Suffix</label>
                       <input type="text" name="dealSuffix" value={formData.dealSuffix} onChange={handleInputChange} className="w-full bg-white border-none rounded-xl px-4 py-3 text-xs focus:ring-2 focus:ring-gray-900" placeholder="OFF" />
                     </div>
                   </div>
                </div>
              )}

              {/* Call to Action */}
              <div className="grid grid-cols-2 gap-6 pb-8">
                <div>
                  <label className="block text-[11px] font-bold text-gray-400 uppercase tracking-widest mb-3">CTA Text</label>
                  <input type="text" name="ctaText" value={formData.ctaText} onChange={handleInputChange} className="w-full bg-gray-50 border-none rounded-xl px-4 py-3 text-sm focus:ring-2 focus:ring-gray-900" placeholder="SHOP NOW" />
                </div>
                <div>
                  <label className="block text-[11px] font-bold text-gray-400 uppercase tracking-widest mb-3">CTA Link</label>
                  <input type="text" name="ctaLink" value={formData.ctaLink} onChange={handleInputChange} className="w-full bg-gray-50 border-none rounded-xl px-4 py-3 text-sm focus:ring-2 focus:ring-gray-900" placeholder="/shop" />
                </div>
              </div>
            </form>

            <footer className="px-8 py-6 bg-gray-50 border-t border-gray-100 flex items-center gap-3">
              <button onClick={resetForm} className="flex-1 py-4 px-6 rounded-2xl bg-white border border-gray-200 text-sm font-bold text-gray-600 hover:bg-gray-100 transition-all">Cancel</button>
              <button type="submit" form="ad-form" className="flex-[2] py-4 px-6 rounded-2xl bg-gray-900 text-white text-sm font-bold hover:bg-black transition-all shadow-xl shadow-gray-200 active:scale-95">
                {isEditing ? 'Save Changes' : 'Publish Advertisement'}
              </button>
            </footer>
          </div>
        </div>
      )}

      {/* Toast */}
      {toast.show && (
        <div className={`fixed bottom-8 right-8 z-[100] px-6 py-4 rounded-2xl shadow-2xl flex items-center gap-3 animate-slideUp ${toast.type === 'error' ? 'bg-red-600 text-white' : 'bg-gray-900 text-white'}`}>
           {toast.type === 'error' ? (
             <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
           ) : (
             <svg className="w-5 h-5 text-green-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
           )}
           <span className="text-sm font-bold tracking-tight">{toast.message}</span>
        </div>
      )}
    </div>
  );
};

export default AdvertisementManager;
